import * as React from 'react';
import { cva, type VariantProps } from 'class-variance-authority';

const alertVariants = cva(
  'relative w-full rounded-lg border p-4 bg-background text-foreground',
  {
    variants: {
      variant: {
        default: 'border-border text-foreground',
        destructive: 'border-destructive/50 text-destructive dark:border-destructive',
        success: 'border-emerald-500/50 text-emerald-600 dark:text-emerald-400'
      }
    },
    defaultVariants: { variant: 'default' }
  }
);

export function AlertBanner({ title, children, variant }: { title: string; children: React.ReactNode; variant?: 'default' | 'destructive' | 'success'; }) {
  return (
    <div role="alert" className={alertVariants({ variant })}>
      <h5 className="font-medium leading-none tracking-tight">{title}</h5>
      <div className="text-sm text-muted-foreground mt-2">{children}</div>
    </div>
  );
}
